 for en,zh,loc,n in [('Khai-Zhan','凯詹','948','沿865已定地名'),('Khai-Zhan Uprising','凯詹叛乱','948','同一星球事件'),('Vogen','沃根','948','首都'),("Sniper’s Alley",'狙击手之巷','948','沃根法庭周围街道'),('Cadia Prime','卡迪亚主星','949','Prime非数字一'),('Inquisitor-General Neve','审判总长内夫','949','General在此为总负责人，职衔暂定'),('axeltree','轴木','949','树木名称，非已知针叶树分类'),('Baphomael','巴普梅尔','949','亚空间风暴'),('Cadian Interior Guard','卡迪亚内卫','949','行星防御部队'),('Internal Guard','内部卫队','949','恶魔审判庭借调人员组成，不与内卫混同'),('Month of Making','成材月','949','儿童接受生存试炼的时期，原制造月'),('Governor Primus','首席总督','949','卡迪亚总督军职'),('shatrovy','沙特罗维堡','949','本地防御工事'),('Law of Decipherability','碑文可辨法','949','原解密法，实际依墓碑可读性决定墓地是否重用')]:f.write('\t'.join([en,zh,'暂定·官方待核','所给英文底稿',loc,n])+'\n')
